import{_ as e,o as i,c as o,a2 as t}from"./chunks/framework.BN2sqjC1.js";const u=JSON.parse('{"title":"M6-WP1 — Benchmark della Graph view","description":"","frontmatter":{},"headers":[],"relativePath":"qa/m6-graph-benchmark.md","filePath":"qa/m6-graph-benchmark.md"}'),r={name:"qa/m6-graph-benchmark.md"};function n(s,a,d,l,c,m){return i(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="m6-wp1-—-benchmark-della-graph-view" tabindex="-1">M6-WP1 — Benchmark della Graph view <a class="header-anchor" href="#m6-wp1-—-benchmark-della-graph-view" aria-label="Permalink to &quot;M6-WP1 — Benchmark della Graph view&quot;">​</a></h1><p>Obiettivo (roadmap M6-WP1): grafo di 10k nodi a ≥ 30 fps. Questo documento riporta ciò che è stato misurato davvero, il metodo e i limiti. Nessun valore è stato stimato.</p><h2 id="ambiente" tabindex="-1">Ambiente <a class="header-anchor" href="#ambiente" aria-label="Permalink to &quot;Ambiente&quot;">​</a></h2><p>MacBook (Apple M4), macOS, Go 1.26, Node 24, Chromium di Playwright 1.64 in modalità <strong>headless</strong> (rasterizzazione CPU software, nessuna GPU). Grafo sintetico (<code>src/graph/synthetic.ts</code>): 10 000 nodi, ~35 000 archi, distribuzione dei gradi a coda pesante. Durante le misure la macchina era condivisa con altri processi (load average 6-14 sui 10 core), quindi i tempi variano: sono riportati gli intervalli osservati.</p><h2 id="_1-backend-graph-build-su-vault-sintetico-da-10k-note" tabindex="-1">1. Backend: <code>graph.Build</code> su vault sintetico da 10k note <a class="header-anchor" href="#_1-backend-graph-build-su-vault-sintetico-da-10k-note" aria-label="Permalink to &quot;1. Backend: `graph.Build` su vault sintetico da 10k note&quot;">​</a></h2><p><code>cd apps/desktop &amp;&amp; go test -run xxx -bench Build -benchtime 3x ./internal/graph/</code></p><p>Vault reale su disco indicizzato dall&#39;indexer (10 000 note, ~5 link ciascuna, tag, fantasmi), <code>Build</code> con orfani, fantasmi e tag attivi:</p><ul><li><strong>~83 ms per chiamata</strong> (10 060 nodi, 60 990 archi). Numero fisso di query, nessun N+1.</li><li>L&#39;indicizzazione iniziale del vault sintetico (non parte di <code>Build</code>) richiede minuti ed è fuori da questo benchmark.</li></ul><h2 id="_2-layout-passo-di-simulazione" tabindex="-1">2. Layout (passo di simulazione) <a class="header-anchor" href="#_2-layout-passo-di-simulazione" aria-label="Permalink to &quot;2. Layout (passo di simulazione)&quot;">​</a></h2><p><code>MEMOBRAIN_GRAPH_BENCH=10000 yarn workspace @memobrain/desktop-frontend exec vitest run src/graph/layout.bench.test.ts</code> (d3-force in Node/V8, thread principale, quindi senza il costo del Worker):</p><table tabindex="0"><thead><tr><th>nodi</th><th>archi</th><th>tick (mediana)</th><th>tick (p95)</th><th>tick fino a raffreddamento</th></tr></thead><tbody><tr><td>2 000</td><td>6 942</td><td>4,05 ms</td><td>4,61 ms</td><td>300, 1,2 s</td></tr><tr><td>10 000</td><td>35 001</td><td>19,3 ms</td><td>23,8 ms</td><td>194, 3,9 s</td></tr></tbody></table><p>Nell&#39;app il layout gira in un Web Worker e pubblica le posizioni circa a ogni frame: l&#39;interfaccia non è bloccata; il grafo da 10k si assesta in ~5-8 s (misura in browser, sotto).</p><h2 id="_3-rendering-in-chromium-reale" tabindex="-1">3. Rendering in Chromium reale <a class="header-anchor" href="#_3-rendering-in-chromium-reale" aria-label="Permalink to &quot;3. Rendering in Chromium reale&quot;">​</a></h2><p><code>MEMOBRAIN_GRAPH_BENCH=10000 yarn workspace @memobrain/desktop-frontend exec playwright test e2e/graph-bench.spec.ts</code></p><p>Il test usa il Worker vero e il renderer Canvas 2D vero; la durata di disegno include una lettura di 1 pixel (<code>getImageData</code>) per forzare la rasterizzazione, altrimenti il tempo JS nasconde il costo di raster. Due fasi:</p><ul><li><strong>Frame completo</strong> (durante il layout, vista fissa, ridisegno esatto di 10k nodi e ~35k archi): mediana <strong>14,7 ms</strong> (carico basso) / <strong>21,5 ms</strong> (macchina carica), p95 15-23 ms, massimo 31-54 ms → circa 45-65 fps possibili.</li><li><strong>Pan/zoom continuo</strong> (4 s di eventi <code>wheel</code> a ogni frame; si trasforma il bitmap): <strong>60,1 fps</strong>, 2 ms per frame, intervalli rAF 16,7 ms.</li></ul><p>Prima delle ottimizzazioni (archi a 1,2 px, archi circolari per ogni nodo) lo stesso test dava 0,5-1,9 fps nello stesso browser: gli archi non-hairline dominavano (misura isolata: 35k segmenti, 37 ms a 1 px contro 1 900 ms a 1,2 px).</p><h2 id="cosa-non-e-stato-verificato" tabindex="-1">Cosa NON è stato verificato <a class="header-anchor" href="#cosa-non-e-stato-verificato" aria-label="Permalink to &quot;Cosa NON è stato verificato&quot;">​</a></h2><ul><li>Il webview reale di Wails (WKWebView/WebView2/WebKitGTK) con accelerazione GPU: le cifre sopra sono di Chromium headless con raster CPU, quindi un ordine di grandezza di riferimento prudente, non una garanzia per ogni piattaforma. Da ripetere su macOS/Windows/Linux con l&#39;app (<code>task dev-desktop</code>) aprendo il grafo di un vault grande.</li><li>Il tempo <code>Build</code> end-to-end tramite binding Wails (serializzazione JSON di ~10k nodi) non è stato misurato separatamente.</li><li>Hardware meno recente di un M4: i tick di layout (CPU, nel Worker) scalano con la CPU; il frame completo a 10k nodi potrebbe scendere sotto 30 fps su portatili lenti con raster CPU. In tal caso le leve già previste sono: <code>maxNodes</code> più basso, <code>labelZoom</code> più alto, passaggio a <code>pixi.js</code> (vedi ADR-0013).</li></ul>',19)])])}const h=e(r,[["render",n]]);export{u as __pageData,h as default};
